  ?zone a brick:Zone .
  FILTER (label(?zone) = "Perimeter_bot_ZN_2" || label(?zone) = "DataCenter_mid_ZN_6")
}

SELECT ?z WHERE {
  ?z a brick:Zone ; rdfs:label ?l .
  FILTER (?l = "Perimeter_bot_ZN_2" || ?l = "DataCenter_mid_ZN_6")
}

SELECT ?zone ?sensor ?ts WHERE {
  ?sensor brick:hasLocation ?zone ; a brick:AirTemperatureSensor .
  ?zone a brick:Zone .
  FILTER (STR(?zone) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z03" || STR(?zone) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z08")
  ?sensor ref:hasExternalReference [ ref:hasTimeseriesId ?ts ] .
}

SELECT ?sensor ?ref ?ts WHERE {
  ?sensor a brick:AirTemperatureSensor ;
          brick:hasLocation ?zone .
  FILTER (STR(?zone) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z03" || STR(?zone) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z08")
  OPTIONAL { ?sensor ?p ?o . }
}

SELECT ?s ?p ?o WHERE {
  ?zone a brick:Zone .
  FILTER (STR(?zone) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z03")
  ?s ?p ?o .
  FILTER (STR(?s) = STR(?zone) || STR(?o) = STR(?zone))
}

